import re, sys

PATH = '/dayjs/src/plugin/timezone/index.js'
CANON = 'const localTs = d.utc(input).valueOf()'

def dtz_body(src):
    m = re.search(r'd\.tz\s*=\s*function\s*\(input,\s*timezone\)\s*\{', src)
    if not m:
        return None, None, None
    start = m.end()
    depth = 1
    i = start
    while i < len(src) and depth > 0:
        if src[i] == '{':
            depth += 1
        elif src[i] == '}':
            depth -= 1
        i += 1
    return start, i - 1, src[start:i - 1]

def has_bad(body):
    if body is None:
        return False
    if 'typeof input' in body:
        return True
    if re.search(r'(?<![.\w])d\(input\)', body):
        return True
    return False

def strip_typeof(lines):
    idx = next((i for i, l in enumerate(lines) if 'typeof input' in l), None)
    if idx is None:
        return lines
    # ternary assignment on the same line?
    if re.search(r'(const|let|var)\s+localTs\s*=', lines[idx]):
        lines[idx] = CANON
        return lines
    # otherwise an if/else block: delete it by brace matching
    depth = 0
    started = False
    endidx = idx
    for j in range(idx, len(lines)):
        depth += lines[j].count('{') - lines[j].count('}')
        if '{' in lines[j]:
            started = True
        if started and depth <= 0:
            endidx = j
            break
    del lines[idx:endidx + 1]
    return lines

def fix(src):
    start, end, body = dtz_body(src)
    if body is None or not has_bad(body):
        return src, False
    lines = body.split('\n')
    if 'typeof input' in body:
        lines = strip_typeof(lines)
        # drop orphan `let localTs` declarations
        if not any(re.search(r'localTs\s*=', l) for l in lines):
            lines = [l for l in lines if not re.match(r'\s*(let|var)\s+localTs\s*;?\s*$', l)]
        # ensure canonical line present
        if not any(CANON in l for l in lines):
            ti = next((i for i, l in enumerate(lines)
                       if re.search(r'const\s*\[\s*targetTs', l) or 'fixOffset(' in l), None)
            if ti is None:
                ti = len(lines)
            lines.insert(ti, CANON)
    # replace any remaining bare d(input) with d.utc(input)
    body2 = '\n'.join(lines)
    body2 = re.sub(r'(?<![.\w])d\(input\)', 'd.utc(input)', body2)
    if body2 == body:
        return src, False
    return src[:start] + body2 + src[end:], True

with open(PATH) as f:
    src = f.read()
new, changed = fix(src)
if changed:
    with open(PATH, 'w') as f:
        f.write(new)
    print('FIXED')
else:
    start, end, body = dtz_body(src)
